        'from .lattice import _shadow_pose_points, _shadow_collision, _shadow_points\n'
        '\n'
        '\n'
        '@dataclass\n'
        'class PlannerControlSettings:\n'
        '    """Opt-in consumer of the fresh lattice; baseline remains the default.\n'
        '\n'
        '    There is no fixed source-trajectory TTL or steering/curvature admission\n'
        '    threshold. Fresh feedback, rolling known-boundary checks and remaining\n'
        "    preview coverage decide whether to use the path or this cycle's baseline.\n"
        '    """\n'
        '    enabled: bool = False\n'
        '\n'
        '    def __post_init__(self):\n'
        '        if not isinstance(self.enabled, bool):\n'
        '            raise ValueError("planner_control.enabled must be boolean")\n'
        '\n'
        '\n'
        'class PlannerExecutionManager:\n'
        '    """Geometry-only high-rate adapter; never publishes actions or requests Stop.\n'
        '\n'
        "    A result's input pose/epoch survives arbitrarily long computation. The\n"
        '    short execution reference is rebuilt at each CURRENT state timestamp;\n'
        '    source age is retained separately and cannot be renewed by reception.\n'
        '    Only the selected path is checked, without a controller rollout or cost.\n'
        '    """\n'
        '    def __init__(self, frame_id="base_link", generation=None):\n'
        '        self.frame_id = frame_id\n'
        '        self.clear(generation=generation)\n'
        '\n'
        '    def clear(self, reason="waiting_for_planner", generation=None):\n'
        '        self.generation = generation\n'
        '        self.active = None\n'
        '        self.reason = reason\n'
        '        self.last_job_id = None\n'
        '        self.last_result_stamp_s = None\n'
        '        self.last_result_status = None\n'
        '        self.diagnostics = {}\n'
        '        self.latest_input_stamp_s = None\n'
        '        self.last_rejected_result = None\n'
        '\n'
        '    def accept(self, result):\n'
        '        # Reject obsolete transport results before touching the current path.\n'
        '        # This does not add a road/geometry admission condition.\n'
        '        identifier, stamp = result.get("job_id"), result.get("input_stamp_s")\n'
        '        reason = None\n'
        '        transport_failure = result.get("status") == "TRANSPORT_ERROR"\n'
        '        if not transport_failure and self.generation is not None and result.get("generation") != self.generation:\n'
        '            reason = "old_generation"\n'
        '        elif identifier is not None and (type(identifier) is not int or identifier < 0):\n'
        '            reason = "invalid_job_id"\n'
        '        elif identifier is not None and self.last_job_id is not None and identifier <= self.last_job_id:\n'
        '            reason = "old_job"\n'
        '        elif (finite_number(stamp) and finite_number(self.latest_input_stamp_s)\n'
        '                and stamp < self.latest_input_stamp_s):\n'
        '            reason = "old_input_stamp"\n'
        '        if reason:\n'
        '            self.last_rejected_result = dict(reason=reason, generation=result.get("generation"), job_id=identifier)\n'
        '            return False\n'
        '        if self.generation is None and result.get("generation") is not None:\n'
        '            self.generation = result["generation"]\n'
        '        if finite_number(stamp):\n'
        '            self.latest_input_stamp_s = stamp\n'
        '        # A completed planning failure immediately selects baseline, rather\n'
        '        # than silently continuing the previous successful trajectory.\n'
        '        self.active = None\n'
        '        if identifier is not None:\n'
        '            self.last_job_id = identifier\n'
        '        self.last_result_stamp_s = result.get("input_stamp_s")\n'
        '        self.last_result_status = result.get("status")\n'
        '        self.reason = "planner_"+str(result.get("status", "missing_status")).lower()\n'
        '        if result.get("status") != "VALID":\n'
        '            return True\n'
        '        anchor = result.get("execution_anchor") or {}\n'
