        '\n'
        '    def prepare(self, estimates, baseline, source, cfg, planning, control, update_rate_hz):\n'
        '        """Same path selection for both callers; baseline geometry is not a gate."""\n'
        '        try:\n'
        '            road = estimates.get("road") or {}\n'
