        '            "source_age_s": now-self.last_result_stamp_s if finite_number(now)\n'
        '                and finite_number(self.last_result_stamp_s) else None}\n'
        '\n'
        '        def fallback(reason):\n'
        '            self.diagnostics.update(reason=reason, elapsed_s=time.perf_counter()-started)\n'
        '            return None\n'
        '\n'
        '        active = self.active\n'
        '        if active is None:\n'
        '            return fallback(self.reason)\n'
        '        if epoch != active["epoch"]:\n'
        '            self.active = None\n'
        '            self.reason = "motion_epoch_changed"\n'
        '            return fallback(self.reason)\n'
        '        if (state.get("frame_id") != self.frame_id or state.get("speed_valid") is not True\n'
        '                or state.get("yaw_rate_valid") is not True or not finite_number(now)\n'
        '                or now < active["stamp_s"] or not all(finite_number(v) for v in pose)):\n'
        '            return fallback("execution_motion_unavailable")\n'
        '        points = _shadow_pose_points(active["path"], active["pose"], pose)\n'
        '        arc = _path_lengths(points)\n'
        '        # Remove previously passed arc BEFORE projecting: a returning leg may\n'
        '        # remain ahead; deleting by x sign would destroy genuine U bends.\n'
        '        start = active["progress_m"]\n'
        '        local = [_path_sample(points, arc, start)]\n'
        '        local.extend(p for p, s in zip(points, arc) if s > start+1e-6)\n'
        '        if len(local) < 2:\n'
        '            return fallback("preview_coverage_exhausted")\n'
        '        local_arc = _path_lengths(local)\n'
        '        nearest = _path_project(local, local_arc)\n'
        '        if nearest is None:\n'
        '            return fallback("execution_branch_unavailable")\n'
        '        progress = min(arc[-1], start+nearest[1])\n'
        '        active["progress_m"] = progress\n'
        '        remaining = arc[-1]-progress\n'
        '        speed = abs(state["speed_mps"])\n'
        '        needed = preview_m+speed*control_period_s\n'
        '        self.diagnostics.update(progress_m=progress, remaining_length_m=remaining,\n'
        '            preview_m=preview_m, required_coverage_m=needed,\n'
        '            remaining_preview_time_s=max(0.0, remaining-preview_m)/speed if speed > 1e-9 else None,\n'
        '            measurement_stamp_s=active["measurement_stamp_s"], odometry_epoch=epoch,\n'
        '            current_pose=list(pose), execution_lifetime_s=execution_lifetime_s)\n'
        '        if remaining+1e-9 < needed:\n'
