        '                    raise ValueError("Control cached curve no longer y(x)")\n'
        '            predicted_path = {"type": "CARTESIAN_Y_OF_X", "independent_variable": "x_m",\n'
        '                              "origin": 0.0, "scale": 1.0,\n'
        '                              "coeffs_low_to_high": [intercept, slope],\n'
        '                              "range": [max(0.0, x0), x1]}\n'
        '\n'
        '        selected = control_reference_snapshot(reference if usable else self.reference)\n'
        '        if not usable:\n'
        '            selected["path"] = predicted_path\n'
        '            if self.curve_samples is not None:\n'
        '                selected["path"] = deepcopy(self.reference["path"])\n'
