        '        self.get_logger().info(\n'
        '            f"Policy update source: {self.policy_update_mode}; required sensors: "\n'
        '            f"{list(self.required_sensors)}; namespace: {self.get_namespace()}")\n'
        '\n'
        '    def _validate_parameters(self):\n'
        '        if self.policy_update_mode not in ("cone_detection", "fiducial_detection", "lidar", "timer"):\n'
        '            raise ValueError(\n'
        '                "policy_update_mode must be cone_detection, fiducial_detection, lidar, or timer")\n'
        '        required = self.required_sensors\n'
        '        if not isinstance(required, (list, tuple)) or not all(isinstance(s, str) for s in required):\n'
        '            raise ValueError("required_sensors must be a list of sensor names")\n'
        '        if len(set(required)) != len(required) or any(s not in SENSORS for s in required):\n'
        '            raise ValueError(f"required_sensors must contain unique names from {SENSORS}")\n'
        '        trigger = {"cone_detection": "cone_detections",\n'
        '                   "fiducial_detection": "fiducial_detections"}.get(self.policy_update_mode)\n'
        '        if trigger is not None and trigger not in required:\n'
        '            raise ValueError(f"{self.policy_update_mode} mode requires {trigger} in required_sensors")\n'
        '        if self.policy_update_mode == "lidar" and not {"lidar_scan", "lidar_cartesian"}.intersection(required):\n'
        '            raise ValueError("lidar mode requires lidar_scan or lidar_cartesian in required_sensors")\n'
        '        positive = {"policy_update_rate_hz": self.policy_update_rate_hz,\n'
        '                    "cone_empty_timeout_s": self.cone_empty_timeout_s,\n'
        '                    "supervision_rate_hz": self.supervision_rate_hz,\n'
        '                    "status_period_s": self.status_period_s, **self.sensor_timeout_s}\n'
        '        for name, value in positive.items():\n'
        '            if not finite_number(value) or value <= 0.0 or not math.isfinite(1.0 / value):\n'
        '                raise ValueError(f"{name} must be finite and positive")\n'
        '        # ROS timers have nanosecond resolution: reject a period that truncates\n'
        '        # to zero, rather than accidentally creating a continuously-ready timer.\n'
        '        if max(self.policy_update_rate_hz, self.supervision_rate_hz) > 1e9:\n'
        '            raise ValueError("timer frequencies cannot exceed nanosecond resolution")\n'
        '        if not finite_number(self.timestamp_tolerance_s) or self.timestamp_tolerance_s < 0.0:\n'
        '            raise ValueError("timestamp_tolerance_s must be finite and nonnegative")\n'
        '        if not valid_frame(self.policy_frame_id):\n'
        '            raise ValueError("policy_frame_id must be a nonempty frame without whitespace or leading /")\n'
