        '\n'
        '    # ---- Control-only reference recovery; upstream algorithms stay unchanged --\n'
        '    def _select_planner_reference(self, estimates):\n'
        '        return self.planner_execution.prepare(estimates, self.planning_output, self,\n'
        '            self.shadow_settings, self.planning_settings, self.control_settings, self.policy_update_rate_hz)\n'
        '\n'
        '    def _publish_planner_execution(self):\n'
        '        """Record every executed control tick; transport faults cannot stop it."""\n'
        '        try:\n'
        '            enabled = self.planner_control_settings.enabled\n'
        '            info = dict(self.planner_execution.diagnostics) if enabled else {\n'
        '                "requested_source": "baseline", "mode": "baseline", "fallback": False,\n'
        '                "reason": "baseline_selected"}\n'
        '            control = self.control_diagnostics or {}\n'
        '            memory = getattr(self, "learned_policy_memory", None)\n'
        '            worker=getattr(self,"shadow_worker",None)\n'
        '            info["planner_transport"]={"submitted_job_id":getattr(self,"shadow_job_id",None),\n'
        '                "last_submit_s":getattr(self,"shadow_last_submit_s",None),\n'
        '                "status":getattr(worker,"status",None),\n'
        '                "worker_pid":getattr(getattr(worker,"process",None),"pid",None)}\n'
        '            if not finite_number(info["planner_transport"]["last_submit_s"]):\n'
        '                info["planner_transport"]["last_submit_s"]=None\n'
        '            info["selection_backend"] = "learned_policy" if memory is not None else "native"\n'
        '            if memory is not None:\n'
        '                info["learned_policy"] = memory.diagnostics()\n'
        '            if getattr(self, "_gyro_fallback_active", False):\n'
        '                info.update(mode="gyro_fallback", fallback=True,\n'
        '                    reason="gyro_unavailable_camera_tracking", reference_source="camera",\n'
        '                    drive_action=control.get("drive_action"), steering_action=control.get("steering_action"),\n'
        '                    motion_compensated=False)\n'
        '            ref = getattr(self, "_trajectory_reference", None) or {}\n'
        '            info.update(timestamp_s=ref.get("timestamp_s"), generation=self.shadow_generation,\n'
        '                reference_version=ref.get("planner_version"),\n'
        '                baseline_valid=bool(self.planning_output and self.planning_output.get("valid")),\n'
        '                baseline_reason=(self.planning_output or {}).get("reason"),\n'
        '                speed_mps=(self.estimation_output or {}).get("state", {}).get("speed_mps"),\n'
        '                preview_xy_m=[control.get("preview_x_m"), control.get("preview_y_m")],\n'
        '                heading_error_rad=control.get("heading_error_rad"),\n'
        '                steer_before_slew=control.get("steer_before_slew"),\n'
        '                steer_after_slew=info.get("steering_action"),\n'
        '                reference_valid_for_s=ref.get("valid_for_s"))\n'
        '            if self.fsm_state != FSM_STATE_PUBLISHING_POLICY_ACTION:\n'
        '                info.update(mode="idle", fallback=False, reason=self.state_reason)\n'
        '            self.planner_execution_publisher.publish(String(data=json.dumps(info, allow_nan=False)))\n'
        '            mode = (info.get("mode", "pending"), info.get("reason", "waiting_for_reference"))\n'
