        '\n'
        '    def _robust_control_enabled(self):\n'
        '        cfg = self.control_settings\n'
        '        return (cfg.enabled and cfg.mode == "mvp" and cfg.robustness_enabled\n'
        '                and not getattr(self, "_gyro_fallback_active", False))\n'
        '\n'
        '    def _control_health_problem(self, monotonic_now, ros_now_ns):\n'
        '        if getattr(getattr(self, "lidar_obstacle_settings", None), "enabled", False):\n'
        '            problem = self._lidar_stop_problem(monotonic_now, ros_now_ns)\n'
        '            if problem:\n'
        '                return problem\n'
        '        problem = self.health_problem(monotonic_now, ros_now_ns)\n'
        '        if self._gyro_fallback_enabled():\n'
        '            gyro = self.observations.get("imu_angular_velocity")\n'
        '            if (getattr(self, "_gyro_fallback_active", False) or gyro is None\n'
        '                    or self._age(gyro, monotonic_now, ros_now_ns) >= min(\n'
        '                        self.sensor_timeout_s["imu_angular_velocity"],\n'
        '                        self.estimation_settings.motion_max_gap_s,\n'
        '                        self.estimation_settings.max_source_age_s)):\n'
        '                # Camera-only mode cannot bridge camera/road loss with a cache.\n'
        '                if problem:\n'
        '                    return problem\n'
        '                for name, limit in (("cone_detections", min(\n'
        '                        self.control_settings.gyro_fallback_max_camera_age_s,\n'
        '                        self.estimation_settings.max_source_age_s,\n'
        '                        self.sensor_timeout_s["cone_detections"])),\n'
        '                        ("wheel_speed", min(self.estimation_settings.motion_max_gap_s,\n'
        '                         self.estimation_settings.max_source_age_s,\n'
        '                         self.sensor_timeout_s["wheel_speed"]))):\n'
        '                    obs = self.observations.get(name)\n'
        '                    if obs is None or self._age(obs, monotonic_now, ros_now_ns) >= limit:\n'
        '                        return f"Gyro fallback required sensor {name} is missing or stale"\n'
        '                if (self.fsm_state == FSM_STATE_PUBLISHING_POLICY_ACTION\n'
        '                        and not getattr(self, "_gyro_fallback_active", False)):\n'
        '                    self._enter_gyro_fallback()\n'
        '                return None\n'
        '        if (getattr(self, "_end_straight_start_distance_m", None) is not None\n'
        '                and problem == "No recent nonempty cone detections"):\n'
        '            # Fresh empty camera frames are expected outside the cone FOV.\n'
        "            # health_problem already checked EVERY required source's freshness.\n"
        '            return None\n'
        '        if not problem or not self._robust_control_enabled():\n'
        '            return problem\n'
        '        # Only cone availability may be bridged. Never exempt wheel/gyro or any\n'
        '        # other required field, even if the cone fault is the first in the list.\n'
        '        for name in self.required_sensors:\n'
        '            if name != "cone_detections" and not self._fresh(name, monotonic_now, ros_now_ns):\n'
        '                return f"Required sensor {name} is missing or stale"\n'
        '        manager = getattr(self, "control_reference_manager", None)\n'
        '        if manager is None or manager.reference is None:\n'
        '            return problem\n'
        '        cache_problem = manager.problem(monotonic_now, self.distance_limiter.distance_m)\n'
        '        if cache_problem:\n'
        '            return cache_problem + "; explicit resume required"\n'
        '        return None\n'
        '\n'
        '    def _select_control_reference(self, estimates):\n'
        '        if not hasattr(self, "control_reference_manager"):\n'
        '            self.control_reference_manager = ControlReferenceManager(self.control_settings)\n'
        '        state = estimates["state"]\n'
        "        # Execution cadence is independent of the planner's remaining ROAD\n"
        '        # lifetime. Fresh motion is checked each cycle; the original source\n'
        '        # timestamps and hold budgets are kept independently in the cache.\n'
        '        ages = state.get("source_age_s") or {}\n'
        '        remaining = [self.sensor_timeout_s[name]-ages.get(name, math.inf)\n'
        '                     for name in ("wheel_speed", "imu_angular_velocity")]\n'
        '        return self.control_reference_manager.select(\n'
        '            self.planning_output, estimates["road"], state, self.motion_history,\n'
        '            state["timestamp_s"], self._monotonic(), self.distance_limiter.distance_m,\n'
        '            min(0.2, self.control_settings.max_dt_s, *remaining))\n'
        '\n'
        '    def _report_control_status(self):\n'
        '        manager = self.control_reference_manager\n'
        '        self.control_diagnostics.update(manager.diagnostics)\n'
        '        if manager.reference is None:\n'
        '            return\n'
        '        if manager.mode != getattr(self, "last_control_tracking_mode", None):\n'
        '            self.last_control_tracking_mode = manager.mode\n'
        '            self.state_reason = "Control: " + str(manager.diagnostics)\n'
        '            self.get_logger().info(self.state_reason)\n'
        '            self.publish_state()\n'
        '\n'
        '    # ---- State requests, watchdog, and publication ---------------------------\n'
        '    def fsm_transition_request_callback(self, msg):\n'
        '        requested = msg.data\n'
        '        now, ros_now = self._times()\n'
        '        if requested not in STATE_NAMES:\n'
        '            self._warn("state_request", f"Ignoring invalid policy state request: {requested}")\n'
        '            return\n'
        '        if requested == self.fsm_state:\n'
        '            return  # No accidental heading/integrator/time reset on a repeat.\n'
        '        if requested == FSM_STATE_PUBLISHING_POLICY_ACTION:\n'
        '            problem = None\n'
        '            if getattr(getattr(self, "lidar_obstacle_settings", None), "enabled", False):\n'
        '                problem = self._lidar_stop_problem(now, ros_now)\n'
        '            problem = problem or self.health_problem(now, ros_now)\n'
        '            if problem:\n'
        '                self.state_reason = f"Policy start refused: {problem}"\n'
        '                self.get_logger().warning(self.state_reason)\n'
        '                self.publish_state()\n'
        '                return\n'
        '            self.heading_reference = None\n'
        '            if self._fresh("imu_orientation", now, ros_now):\n'
        '                self.heading_reference = roll_pitch_yaw(self.observations["imu_orientation"].value)[2]\n'
        '            # Optional missing heading stays unavailable until the next real\n'
        '            # policy-state entry; a later IMU sample does not silently re-tare.\n'
        '            self.policy_started_at = now\n'
        '            self.previous_policy_step_at = None\n'
        '        self._change_state(requested, "Operator request")\n'
        '\n'
        '    def _change_state(self, state, reason):\n'
        '        self.fsm_state = state\n'
        '        self.state_reason = reason\n'
        '        if hasattr(self, "stop_feedback"):\n'
        '            self.stop_feedback.reset(state, self._monotonic())\n'
        "        # An internal consumer must not mistake the previous run's estimate\n"
        '        # for an active result after a stop, source expiry, or explicit restart.\n'
        '        self.estimation_output = None\n'
        '        self.motion_history.clear()\n'
        '        if getattr(self, "learned_policy_memory", None) is not None:\n'
        '            self.learned_policy_memory.reset()\n'
        '        self.planning_output = None\n'
        '        self.planning_diagnostics = None\n'
        '        self.controller.clear()\n'
        '        if hasattr(self, "control_reference_manager"):\n'
        '            self.control_reference_manager.clear()\n'
        '        self.last_control_tracking_mode = None\n'
        '        self.control_diagnostics = None\n'
        '        self.last_control_reference_deadline_s = None\n'
        '        self.control_has_run = False\n'
        '        self._gyro_fallback_active = False\n'
        '        if hasattr(self, "planner_execution"):\n'
        '            self.planner_execution.clear()\n'
        '            self._last_execution_mode = None\n'
        '        self._end_straight_start_distance_m = None\n'
        '        self._end_straight_started_at_s = None\n'
        '        if getattr(self, "shadow_worker", None) is not None:\n'
        '            self.shadow_generation += 1\n'
        '            self.shadow_last_submit_s = -math.inf\n'
        '            self.shadow_handoff_estimate_s = self.shadow_settings.handoff_allowance_s\n'
        '            self.shadow_last_result_s = None\n'
        '            self.shadow_road_history = []\n'
        '            self.shadow_pose_stamp_s = None\n'
        '            self.shadow_pose = [0.0, 0.0, 0.0]\n'
        '            self.shadow_odometry_epoch = getattr(self, "shadow_odometry_epoch", 0)+1\n'
        '            self.shadow_previous_reference = None\n'
        '            self.shadow_collection_events = []\n'
        '            self.shadow_collection_reset_id = 0\n'
        '        if state == FSM_STATE_PUBLISHING_POLICY_ACTION:\n'
        '            wheel = self.observations.get("wheel_speed")\n'
        '            speed = wheel.value if wheel is not None else None\n'
        '            self.distance_limiter.reset(self._monotonic(), speed)\n'
        '        if state == FSM_STATE_PUBLISHING_ZERO_ACTIONS:\n'
        '            if self.control_settings.enabled:\n'
        '                self.debug2_publisher.publish(Float32(data=float(self.distance_limiter.distance_m)))\n'
        '            self.publish_zero_actions()\n'
        '        self.get_logger().info(f"{STATE_NAMES[state]}: {reason}")\n'
        '        self.publish_state()\n'
        '        self._trajectory_reference = None\n'
        '        if hasattr(self, "trajectory_publisher"):\n'
        '            self._publish_trajectory(self.get_clock().now().nanoseconds, force=True)\n'
        '            self._trajectory_last_publish_s = -math.inf\n'
        '        # Baseline state/zero publications have priority over shadow diagnostics.\n'
        '        if getattr(self, "shadow_worker", None) is not None:\n'
        '            self._shadow_clear()\n'
        '        if hasattr(self, "planner_execution_publisher"):\n'
        '            self._publish_planner_execution()\n'
        '\n'
        '    def _shadow_clear(self):\n'
        '        """Clear shadow displays on every run boundary; old results are fenced."""\n'
        '        if getattr(self, "learned_policy_memory", None) is not None:\n'
        '            self.learned_policy_memory.pending = None\n'
        '        if hasattr(self, "planner_execution"):\n'
        '            self.planner_execution.clear(generation=self.shadow_generation)\n'
        '        try:\n'
        '            stamp = self.get_clock().now().nanoseconds/1e9\n'
        '            for publisher in (self.shadow_path_publisher, self.shadow_prefix_publisher,\n'
        '                              self.shadow_reference_publisher):\n'
        '                self._shadow_publish_path(publisher, [], stamp)\n'
        '            self.shadow_diagnostics_publisher.publish(String(data=json.dumps({\n'
        '                "status": "IDLE", "generation": self.shadow_generation,\n'
        '                "shadow_only": not bool(getattr(getattr(self, "planner_control_settings", None), "enabled", False))})))\n'
        '        except Exception as error:\n'
        '            self._warn("shadow_clear", f"Shadow display clearing unavailable: {error}")\n'
