        '    def _shadow_poll(self):\n'
        '        try:\n'
        '            result = self.shadow_worker.poll()\n'
        '            if result is None:\n'
        '                return\n'
        '            if result.get("status") == "TRANSPORT_ERROR":\n'
        '                self._warn("shadow_worker", "Shadow worker failed: "+result.get("error", "unknown"))\n'
        '                self._shadow_clear()\n'
        '                if getattr(getattr(self, "planner_control_settings", None), "enabled", False):\n'
        '                    self.planner_execution.accept(result)\n'
        '                self.shadow_diagnostics_publisher.publish(String(data=json.dumps(result)))\n'
        '                self.shadow_worker.close()\n'
