        '            stamp = stamp if finite_number(stamp) else self.get_clock().now().nanoseconds/1e9\n'
        '            selected = result.get("selected")\n'
        '            safe = result.get("status") == "VALID"\n'
        '            path = selected["path"] if selected and safe else []\n'
        '            prefix = []\n'
        '            if path:\n'
        '                arc = _shadow_lengths([p[:2] for p in path])\n'
        '                end = min(result["check_length_m"], arc[-1])\n'
        '                prefix = [p for p, s in zip(path, arc) if s <= end]\n'
        '                if end > 0:\n'
