        '            return "Control startup history deadline exceeded; explicit resume required"\n'
        '        return None\n'
        '\n'
        '    def _lidar_stop_problem(self, monotonic_now, ros_now_ns):\n'
        '        """Observe once per scan, check freshness each tick; never enable/resume."""\n'
        '        cfg = self.lidar_obstacle_settings\n'
        '        raw, cart = (self.observations.get(name) for name in ("lidar_scan", "lidar_cartesian"))\n'
