        '                self._warn("lidar_status", "LiDAR status publication unavailable: " + str(error))\n'
        '        if result["status"] != "CLEAR":\n'
        '            return "Lidar stop: " + result["reason"] + "; explicit resume required"\n'
        '        return None\n'
        '\n'
        '    def _publish_stop_feedback(self, now, ros_now):\n'
        '        """Independent confirmation; never changes actuation or resumes policy."""\n'
        '        try:\n'
        '            wheel = self.observations.get("wheel_speed")\n'
        '            result = self.stop_feedback.update(self.fsm_state,\n'
        '                None if wheel is None else wheel.value,\n'
        '                None if wheel is None else wheel.received_at, now,\n'
        '                wheel is not None and self._fresh("wheel_speed", now, ros_now),\n'
        '                self.sensor_timeout_s["wheel_speed"])\n'
        '            phase = result["phase"]\n'
        '            if phase != self._last_stop_feedback_phase or now-self._last_stop_feedback_publish_s >= 0.1-1e-9:\n'
        '                self.stop_status_publisher.publish(String(data=json.dumps(result, allow_nan=False)))\n'
        '                self.stop_state_publisher.publish(Int8(data=result["state"]))\n'
