        '"""MVP2.1 transport; relocated from pinned f11428b, without algorithm tuning."""\n'
        '\n'
        'from copy import deepcopy\n'
        'import json\n'
        'import math\n'
        'from .geometry import finite_number\n'
        'import queue\n'
        'import subprocess\n'
        'import sys\n'
        'import threading\n'
        'import time\n'
        'from . import worker\n'
        '\n'
        '\n'
        'class ShadowJobSource:\n'
        '    """Pure temporal collection and job handoff shared by ROS and simulation."""\n'
        '    def _shadow_collect_road(self, road, stamp):\n'
        '        """Bounded 20 Hz collection; planner execution also calls before control.\n'
        '\n'
        '        Accumulate short read-only motion intervals; no per-frame fitting and no\n'
        "        changes to the estimator's motion history. Alignment faults clear only\n"
        '        shadow memory. Original source epochs are not renewed by reconstruction.\n'
        '        """\n'
        '        previous = getattr(self, "shadow_pose_stamp_s", None)\n'
        '        pose = getattr(self, "shadow_pose", [0.0, 0.0, 0.0])\n'
        '        epoch = getattr(self, "shadow_odometry_epoch", 0)\n'
        '        history = getattr(self, "shadow_road_history", [])\n'
        '        reason, reset = ("bootstrap" if previous is None else "aligned"), False\n'
        '        if previous is not None and stamp != previous:\n'
        '            try:\n'
        '                motion, motion_reason = self.motion_history.pose_between(previous, stamp)\n'
        '            except Exception as error:\n'
        '                motion, motion_reason = None, "motion_exception: "+str(error)\n'
        '            if motion is None:\n'
        '                history, pose, epoch = [], [0.0, 0.0, 0.0], epoch+1\n'
        '                self.shadow_previous_reference = None\n'
        '                reason, reset = motion_reason, True\n'
        '                self.shadow_collection_reset_id = getattr(self, "shadow_collection_reset_id", 0)+1\n'
        '                events = getattr(self, "shadow_collection_events", [])\n'
        '                events.append({"id": self.shadow_collection_reset_id, "stamp_s": stamp,\n'
        '                               "reason": motion_reason, "odometry_epoch": epoch})\n'
        '                self.shadow_collection_events = events[-64:]\n'
        '                if hasattr(self, "_warn"):\n'
        '                    self._warn("shadow_alignment", "Shadow temporal history reset: "+str(motion_reason))\n'
        '            else:\n'
        '                c, s = math.cos(pose[2]), math.sin(pose[2])\n'
        '                pose = [pose[0]+c*motion["dx_m"]-s*motion["dy_m"],\n'
        '                        pose[1]+s*motion["dx_m"]+c*motion["dy_m"], pose[2]+motion["yaw_rad"]]\n'
        '        measurement = road.get("measurement_timestamp_s")\n'
        '        key = measurement if finite_number(measurement) else stamp\n'
        '        history = [h for h in history if stamp-h["stamp_s"] <= self.shadow_settings.fusion_window_s\n'
        '                   and h.get("measurement_key") != key]\n'
        '        keys = ("centerline_xy", "left_boundary_xy", "right_boundary_xy", "boundary_source",\n'
        '                "lane_width_m", "lane_width_source", "inward_offset_m", "status", "visibility",\n'
        '                "timestamp_s", "measurement_timestamp_s", "source_age_s", "time_aligned", "degraded", "frame_id")\n'
        '        snapshot = {"road": {key: deepcopy(road.get(key)) for key in keys}, "stamp_s": stamp,\n'
        '                    "pose": list(pose), "odometry_epoch": epoch, "measurement_key": key}\n'
        '        state = (getattr(self, "estimation_output", None) or {}).get("state") or {}\n'
        '        snapshot["state"] = {key: state.get(key) for key in\n'
        '            ("timestamp_s", "frame_id", "speed_mps", "yaw_rate_rps", "speed_valid", "yaw_rate_valid")}\n'
        '        history.append(snapshot)\n'
        '        self.shadow_road_history = history[-self.shadow_settings.fusion_max_samples:]\n'
        '        self.shadow_pose, self.shadow_pose_stamp_s, self.shadow_odometry_epoch = pose, stamp, epoch\n'
        '        self.shadow_collection_diagnostics = {"status": "RESET" if reset else "BOOTSTRAP" if previous is None else "ALIGNED",\n'
        '            "reason": reason, "reset": reset, "buffer_samples": len(self.shadow_road_history), "odometry_epoch": epoch,\n'
        '            "events": deepcopy(getattr(self, "shadow_collection_events", [])),\n'
        '            "reset_events_total": getattr(self, "shadow_collection_reset_id", 0)}\n'
