        '            "compact_result": True,\n'
        '            "generation": self.shadow_generation, "job_id": self.shadow_job_id,\n'
        '            "submitted_monotonic_s": now, "preview_m": self.planning_settings.preview_m,\n'
        '            "handoff_estimate_s": self.shadow_handoff_estimate_s,\n'
        '            "shadow_pose": list(getattr(self, "shadow_pose", [0.0, 0.0, 0.0])),\n'
        '            "shadow_odometry_epoch": getattr(self, "shadow_odometry_epoch", 0),\n'
        '            "planner_control_enabled": bool(getattr(getattr(self, "planner_control_settings", None), "enabled", False)),\n'
        '            "shadow_only": not bool(getattr(getattr(self, "planner_control_settings", None), "enabled", False))}\n'
        '        if self.shadow_settings.fusion_enabled:\n'
        '            job.update(road_history=deepcopy(getattr(self, "shadow_road_history", [])),\n'
        '                shadow_pose=list(getattr(self, "shadow_pose", [0.0, 0.0, 0.0])),\n'
        '                shadow_odometry_epoch=getattr(self, "shadow_odometry_epoch", 0),\n'
        '                temporal_collection=getattr(self, "shadow_collection_diagnostics", None),\n'
        '                previous_reference=deepcopy(getattr(self, "shadow_previous_reference", None)))\n'
        '        policy = getattr(self, "learned_policy_settings", None)\n'
        '        if policy is not None and policy.enabled:\n'
        '            job.update(learned_policy=vars(policy).copy(),\n'
        '                policy_cruise_speed_mps=self.planning_settings.cruise_speed_mps,\n'
        '                policy_context=self.learned_policy_memory.snapshot(),\n'
        '                policy_observation=dict(frame_id=self.policy_frame_id, timestamp_s=stamp,\n'
        '                    estimation=deepcopy({k: estimates[k] for k in ("state", "road", "obstacles")})))\n'
        '        self.shadow_worker.submit(job)\n'
        '        self.shadow_last_submit_s = now\n'
        '\n'
        '\n'
        'class ShadowWorker:\n'
        '    """Latest-only transport thread and separate CPU process; never block control."""\n'
        '    def __init__(self):\n'
        '        self.source_file = worker.__file__\n'
        '        self.jobs, self.results = queue.Queue(maxsize=1), queue.Queue(maxsize=1)\n'
        '        self.closed = threading.Event()\n'
        '        self.process = None\n'
        '        self.status = "starting"\n'
        '        self.thread = threading.Thread(target=self._serve, name="shadow-transport", daemon=True)\n'
        '        self.thread.start()\n'
        '\n'
        '    @staticmethod\n'
        '    def _replace(mailbox, value):\n'
        '        try:\n'
        '            mailbox.get_nowait()\n'
        '        except queue.Empty:\n'
        '            pass\n'
        '        try:\n'
        '            mailbox.put_nowait(value)\n'
        '        except queue.Full:\n'
        '            pass\n'
        '\n'
        '    def submit(self, job):\n'
        '        if not self.closed.is_set():\n'
        '            self._replace(self.jobs, job)\n'
        '\n'
        '    def poll(self):\n'
        '        try:\n'
        '            return self.results.get_nowait()\n'
        '        except queue.Empty:\n'
        '            return None\n'
        '\n'
        '    def _serve(self):\n'
        '        try:\n'
        '            process = subprocess.Popen([sys.executable, self.source_file, "--shadow-worker"],\n'
        '                stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,\n'
        '                text=True, encoding="utf-8", bufsize=1,\n'
        '                env=dict(__import__("os").environ, OPENBLAS_NUM_THREADS="1", OMP_NUM_THREADS="1",\n'
        '                         MKL_NUM_THREADS="1", BLIS_NUM_THREADS="1"),\n'
        '                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))\n'
        '            self.process = process\n'
        '            self.status = "idle"\n'
        '            if self.closed.is_set():\n'
        '                process.terminate()\n'
        '                return\n'
        '            while not self.closed.is_set():\n'
        '                try:\n'
        '                    job = self.jobs.get(timeout=0.1)\n'
        '                except queue.Empty:\n'
        '                    continue\n'
        '                self.status = "computing"\n'
        '                process.stdin.write(json.dumps(job, allow_nan=False)+"\\n")\n'
        '                process.stdin.flush()\n'
        '                line = process.stdout.readline()\n'
        '                if not line:\n'
        '                    raise RuntimeError("shadow process exited")\n'
        '                result = json.loads(line)\n'
        '                result["wire_json"] = line.rstrip()\n'
        '                result["received_monotonic_s"] = time.monotonic()\n'
        '                result["submitted_monotonic_s"] = job["submitted_monotonic_s"]\n'
        '                self._replace(self.results, result)\n'
        '                self.status = "idle"\n'
        '        except Exception as error:\n'
        '            self.status = "failed"\n'
        '            self._replace(self.results, {"status": "TRANSPORT_ERROR", "error": str(error)})\n'
        '        finally:\n'
        '            if self.process is not None:\n'
        '                if self.process.poll() is None:\n'
        '                    self.process.terminate()\n'
        '                try:\n'
        '                    self.process.communicate(timeout=1.0)\n'
        '                except subprocess.TimeoutExpired:\n'
        '                    self.process.kill()\n'
        '                    self.process.communicate()\n'
        '\n'
        '    def close(self):\n'
        '        self.closed.set()\n'
        '        if self.process is not None and self.process.poll() is None:\n'
        '            self.process.terminate()\n'
